  "learn.psych.4.t":"\u0cac\u0cc1\u0ca6\u0ccd\u0ca7\u0cbf\u0c97\u0cbf\u0c82\u0ca4 \u0cb6\u0cbf\u0cb8\u0ccd\u0ca4\u0cc1",
